        salary_min: this.jobOfferForm.value.salary_min ? parseInt(this.jobOfferForm.value.salary_min) : null,
        salary_max: this.jobOfferForm.value.salary_max ? parseInt(this.jobOfferForm.value.salary_max) : null,
        job_description_id: parseInt(this.jobOfferForm.value.job_description_id),
        requirements: this.requirementsArray.value,
        benefits: this.benefitsArray.value,
        created_by: this.authService.currentUser?.id || 1
      };
